import { test, expect } from '@playwright/test';

test.describe('Data Reviewer Table Verification', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/tables');
  });

  test('Verify table header contains correct column headings', async ({ page }) => {
    const headerRow = await page.getByRole('row', { name: 'Last Name First Name Email Due' });
    expect(await headerRow.innerText()).toContain('Last Name');
    expect(await headerRow.innerText()).toContain('First Name');
    expect(await headerRow.innerText()).toContain('Email');
    expect(await headerRow.innerText()).toContain('Due');
  });

  test('Verify table body contains correct number of rows and specific email', async ({ page }) => {
    const tableRows = await page.getByRole('row', { name: 'Smith jsmith@gmail.com' });
    const allRows = await page.locator('#table1 tbody tr').count();
    expect(allRows).toBe(4);
    expect(await tableRows.innerText()).toContain('Smith');
    expect(await tableRows.innerText()).toContain('jsmith@gmail.com');
  });
});
